    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // Pick the smallest character from s and append it to the result.
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
