            for (int k = 0; k <= sum; k++) {
                if (k >= num) {
                    dp[i][j][k] = dp[i - 1][j][k] || dp[i - 1][j - 1][k - num];
                } else {
                    dp[i][j][k] = dp[i - 1][j][k];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (dp[n][i][sum * i / n]) {
                return true;
            }
        }
    }

    return false;
}

